// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetContext Context tab (context size, bands, re-reads, compactions)
	// (GET /api/context)
	GetContext(ctx context.Context, request GetContextRequestObject) (GetContextResponseObject, error)
	// GetDocker Docker tab (Docker VM, containers by stack, disk use, events)
	// (GET /api/docker)
	GetDocker(ctx context.Context, request GetDockerRequestObject) (GetDockerResponseObject, error)
	// GetFills Fills tab (tool results that fill the context)
	// (GET /api/fills)
	GetFills(ctx context.Context, request GetFillsRequestObject) (GetFillsResponseObject, error)
	// GetGuard Guard tab (per-call guard log figures and tool errors)
	// (GET /api/guard)
	GetGuard(ctx context.Context, request GetGuardRequestObject) (GetGuardResponseObject, error)
	// GetLive Server-Sent Events stream of status, machine, Docker, live-session and activity updates
	// (GET /api/live)
	GetLive(ctx context.Context, request GetLiveRequestObject) (GetLiveResponseObject, error)
	// GetMachine Machine tab (CPU per core, memory, network per interface, disks, top apps)
	// (GET /api/machine)
	GetMachine(ctx context.Context, request GetMachineRequestObject) (GetMachineResponseObject, error)
	// GetMeta Filter values (projects, models, agent types, stacks), band bounds and retention settings
	// (GET /api/meta)
	GetMeta(ctx context.Context, request GetMetaRequestObject) (GetMetaResponseObject, error)
	// GetOverview Overview tab
	// (GET /api/overview)
	GetOverview(ctx context.Context, request GetOverviewRequestObject) (GetOverviewResponseObject, error)
	// GetSessions Sessions tab (session map, timeline, compactions)
	// (GET /api/sessions)
	GetSessions(ctx context.Context, request GetSessionsRequestObject) (GetSessionsResponseObject, error)
	// GetSession One session's detail (selected planet on the Sessions tab)
	// (GET /api/sessions/{session})
	GetSession(ctx context.Context, request GetSessionRequestObject) (GetSessionResponseObject, error)
	// GetStatus Scanner, collector, guard and database state for the header and status line
	// (GET /api/status)
	GetStatus(ctx context.Context, request GetStatusRequestObject) (GetStatusResponseObject, error)
	// GetSubagents Sub-agents tab (runs, context and cost per agent type)
	// (GET /api/subagents)
	GetSubagents(ctx context.Context, request GetSubagentsRequestObject) (GetSubagentsResponseObject, error)
	// GetTokens Tokens tab (tokens and estimated cost by model, kind and day)
	// (GET /api/tokens)
	GetTokens(ctx context.Context, request GetTokensRequestObject) (GetTokensResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

